"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        parts = name.split(":", 1)
        step_name = parts[0]
        arg = parts[1]
        if not step_name:
            raise KeyError(f"no step named {step_name!r}. Known: {', '.join(sorted(STEPS))}")
        if step_name not in STEPS:
            raise KeyError(f"no step named {step_name!r}. Known: {', '.join(sorted(STEPS))}")
        return STEPS[step_name].with_arg(arg)
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

