"""The steps themselves. Each takes text and returns text."""


class Step:
    """One transformation."""

    def apply(self, text: str) -> str:
        raise NotImplementedError


class Upper(Step):
    def apply(self, text: str) -> str:
        return text.upper()


class Strip(Step):
    def apply(self, text: str) -> str:
        return text.strip()


class Squeeze(Step):
    def apply(self, text: str) -> str:
        return " ".join(text.split())


class Truncate(Step):
    _length: int | None

    def __init__(self, length: int | None = None):
        self._length = length

    def with_arg(self, arg: str):
        if arg == "":
            raise ValueError("truncate requires a length argument")
        try:
            length = int(arg)
        except ValueError:
            raise ValueError(f"truncate length must be an integer, got {arg!r}")
        return Truncate(length)

    def apply(self, text: str) -> str:
        if self._length is None:
            raise ValueError("truncate step was not given a length")
        return text[:self._length]

